(4377294, 629695, 65234, '<td valign="top">OK, now that''s funny!  Great pose and wonderfully trashy background with the graffiti and rust spots on the door.</td>', 'OK, now that''s funny!  Great pose and wonderfully trashy background with the graffiti and rust spots on the door.', '2008-01-09 10:43:20.000000', NULL, 1),
(4377295, 629274, 65234, '<td valign="top">So they are.  Well-lit and cute little guys, too.</td>', 'So they are.  Well-lit and cute little guys, too.', '2008-01-09 10:44:07.000000', NULL, 1),
(4377303, 628579, 65234, '<td valign="top">No, I''ve seen some truly evil clowns in this challenge and this one just doesn''t look evil to me.  More like a rodeo-type clown, actually.  Nice DOF and exposure to show this clown off.</td>', 'No, I''ve seen some truly evil clowns in this challenge and this one just doesn''t look evil to me.  More like a rodeo-type clown, actually.  Nice DOF and exposure to show this clown off.', '2008-01-09 10:46:19.000000', NULL, 1),
(4377312, 630808, 65234, '<td valign="top">And we''re back to the evil clowns again!  I must say voting on this challenge has been rather alarming; I may be truly clown-phobic by the time I''m done!  Lighting and DOF enhances the mood.  Definitely one of the successfully scary clowns; well done.</td>', 'And we''re back to the evil clowns again!  I must say voting on this challenge has been rather alarming; I may be truly clown-phobic by the time I''m done!  Lighting and DOF enhances the mood.  Definitely one of the successfully scary clowns; well done.', '2008-01-09 10:49:02.000000', NULL, 1),
(4377315, 629319, 65234, '<td valign="top">Well, this is different (hooray!).  Love the lighting, especially on the balloons.  Kudos to you for creativity in the idea and execution :-)</td>', 'Well, this is different (hooray!).  Love the lighting, especially on the balloons.  Kudos to you for creativity in the idea and execution :-)', '2008-01-09 10:50:34.000000', NULL, 1),
(4377322, 629950, 35892, '<td valign="top">love the expression my pick for top honors</td>', 'love the expression my pick for top honors', '2008-01-09 10:52:48.000000', NULL, 1),
(4377328, 630682, 65234, '<td valign="top">Idea and props are cute; lighting is harsh.  The shadow looks too menacing for the mood of everything else in the shot, so I''d recommend a bounce flash or diffuser and/or fill light from the side to get rid of the shadow.</td>', 'Idea and props are cute; lighting is harsh.  The shadow looks too menacing for the mood of everything else in the shot, so I''d recommend a bounce flash or diffuser and/or fill light from the side to get rid of the shadow.', '2008-01-09 10:53:50.000000', NULL, 1),
(4377333, 630649, 65234, '<td valign="top">Another unique idea (yay!).  Bright and colorful.</td>', 'Another unique idea (yay!).  Bright and colorful.', '2008-01-09 10:55:04.000000', NULL, 1),
(4377349, 630786, 65234, '<td valign="top">Trying to interpret what he''s got in his mouth, either a hand-rolled smokable thing or a burnt piece of wood.  Anyway, colorful image; the eyes being a bit shadowed lends an enigmatic appearance to his expression.</td>', 'Trying to interpret what he''s got in his mouth, either a hand-rolled smokable thing or a burnt piece of wood.  Anyway, colorful image; the eyes being a bit shadowed lends an enigmatic appearance to his expression.', '2008-01-09 10:58:21.000000', NULL, 1),
(4377351, 629236, 65234, '<td valign="top">There''s something delightfully tacky about this ;-)</td>', 'There''s something delightfully tacky about this ;-)', '2008-01-09 10:59:25.000000', NULL, 1);
