(4379162, 630125, 73452, '<td valign="top">Great makeup and emotion.</td>', 'Great makeup and emotion.', '2008-01-09 19:53:35.000000', NULL, 1),
(4379164, 628984, 60047, '<td valign="top">This seems to be more of an artistic de-sat than a clown shot. Neat crop.</td>', 'This seems to be more of an artistic de-sat than a clown shot. Neat crop.', '2008-01-09 19:53:53.000000', NULL, 1),
