(4379186, 630307, 60047, '<td valign="top">The lighting is uneven on the two faces. Other than that this is a great clown shot - good close crop, nice focus.</td>', 'The lighting is uneven on the two faces. Other than that this is a great clown shot - good close crop, nice focus.', '2008-01-09 19:58:10.000000', NULL, 1),
(4379187, 630307, 73452, '<td valign="top">the lighting on the clown on the left is great, but the other is lost in its shadow.  thats my only nit-pick.</td>', 'the lighting on the clown on the left is great, but the other is lost in its shadow.  thats my only nit-pick.', '2008-01-09 19:58:14.000000', NULL, 1),
