INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4379195, 628984, 73452, '<td valign="top">i like the eyes, but the skin is just too blown out for my taste, and the eyelashes and eyebrows are oversharpened.</td>', 'i like the eyes, but the skin is just too blown out for my taste, and the eyelashes and eyebrows are oversharpened.', '2008-01-09 19:59:57.000000', NULL, 1),
(4379198, 629559, 60047, '<td valign="top">This is a fun street photo shot. I love the reactions of the girls in the audience. I wish the light weren''t so harsh and hard to work with.</td>', 'This is a fun street photo shot. I love the reactions of the girls in the audience. I wish the light weren''t so harsh and hard to work with.', '2008-01-09 20:00:32.000000', NULL, 1),
(4379201, 629950, 73452, '<td valign="top">what a great image!  love the expression, and the use of black and white, though clowns are usually very colourfull.  the curvy string is also great at framing the face.  good job!</td>', 'what a great image!  love the expression, and the use of black and white, though clowns are usually very colourfull.  the curvy string is also great at framing the face.  good job!', '2008-01-09 20:00:51.000000', NULL, 1),
(4379202, 630620, 73452, '<td valign="top">great lighting.</td>', 'great lighting.', '2008-01-09 20:01:28.000000', NULL, 1),
(4379207, 630733, 73452, '<td valign="top">not sure where the clown head in this really is...</td>', 'not sure where the clown head in this really is...', '2008-01-09 20:02:27.000000', NULL, 1),
(4379209, 630678, 60047, '<td valign="top">The shadows causes this to look as if it was propped up against a pillow</td>', 'The shadows causes this to look as if it was propped up against a pillow', '2008-01-09 20:03:05.000000', NULL, 1),
(4379210, 628647, 73452, '<td valign="top">nice makeup, but the background is pretty boring.  but i doubt you had barely any control for that.</td>', 'nice makeup, but the background is pretty boring.  but i doubt you had barely any control for that.', '2008-01-09 20:03:18.000000', NULL, 1),
(4379213, 630495, 73452, '<td valign="top">the hair is awesome, and that nose just pops off the screen.</td>', 'the hair is awesome, and that nose just pops off the screen.', '2008-01-09 20:03:54.000000', NULL, 1),
(4379214, 630495, 60047, '<td valign="top">An interesting shot. I wish the eyes were in sharper focus.</td>', 'An interesting shot. I wish the eyes were in sharper focus.', '2008-01-09 20:04:22.000000', NULL, 1),
(4379215, 629319, 73452, '<td valign="top">wow, im not really sure what to make of this...it kinda freaks me out to tell you the truth!</td>', 'wow, im not really sure what to make of this...it kinda freaks me out to tell you the truth!', '2008-01-09 20:04:56.000000', NULL, 1),
(4379217, 630807, 73452, '<td valign="top">colors are pretty flat, but that may be from the age of the toy.</td>', 'colors are pretty flat, but that may be from the age of the toy.', '2008-01-09 20:05:49.000000', NULL, 1),
(4379219, 630708, 60047, '<td valign="top">Another evil clown! You gotta love it. The harsh light has made this shot more difficult for you (dark shadows upper right, harsh light lower left).</td>', 'Another evil clown! You gotta love it. The harsh light has made this shot more difficult for you (dark shadows upper right, harsh light lower left).', '2008-01-09 20:06:18.000000', NULL, 1),
(4379220, 629259, 73452, '<td valign="top">yea, that aint creepy at all...*shudder*</td>', 'yea, that aint creepy at all...*shudder*', '2008-01-09 20:06:30.000000', NULL, 1),
(4379221, 630290, 73452, '<td valign="top">i like the set up of the photo, but it seems so overly processed.</td>', 'i like the set up of the photo, but it seems so overly processed.', '2008-01-09 20:07:39.000000', NULL, 1),
(4379222, 630073, 60047, '<td valign="top">I love your title. I wish the ducks were in sharper focus.</td>', 'I love your title. I wish the ducks were in sharper focus.', '2008-01-09 20:07:49.000000', NULL, 1),
(4379223, 630276, 73452, '<td valign="top">awww, sad image.  poor lil'' guy.  i like the makeup though. maybe a touch up on the makeupon the eyelids would help it even more</td>', 'awww, sad image.  poor lil'' guy.  i like the makeup though. maybe a touch up on the makeupon the eyelids would help it even more', '2008-01-09 20:08:42.000000', NULL, 1),
