(4389125, 629707, 41675, '<td valign="top">Cute little doll. For me, the lighting is too harsh. I do like your border and how you pulled the colors from the clown''s outfit.</td>', 'Cute little doll. For me, the lighting is too harsh. I do like your border and how you pulled the colors from the clown''s outfit.', '2008-01-13 14:13:48.000000', NULL, 1),
(4389129, 630300, 41675, '<td valign="top">For me, the lighting is a bit too bright. I think with a bit better focus and perhaps changing this into a vertical image to give him "breathing" room around the chin, I would have scored it higher.</td>', 'For me, the lighting is a bit too bright. I think with a bit better focus and perhaps changing this into a vertical image to give him "breathing" room around the chin, I would have scored it higher.', '2008-01-13 14:14:49.000000', NULL, 1),
(4389140, 630728, 41675, '<td valign="top">For me, the colors on the face looks so... odd - like too fake or post-processed odd. I like the in your face close up. Gives a spooky feel to your image.</td>', 'For me, the colors on the face looks so... odd - like too fake or post-processed odd. I like the in your face close up. Gives a spooky feel to your image.', '2008-01-13 14:17:14.000000', NULL, 1),
(4389143, 630678, 41675, '<td valign="top">When I look at your image, the flower stands out the most and overpowers the little clown. I like the complimentary background.</td>', 'When I look at your image, the flower stands out the most and overpowers the little clown. I like the complimentary background.', '2008-01-13 14:19:15.000000', NULL, 1),
(4389147, 629402, 41675, '<td valign="top">Had the flash been less harsh and maybe having this as a vertical or getting the man''s arm in on the left instead of being cut off, I would have scored this higher.</td>', 'Had the flash been less harsh and maybe having this as a vertical or getting the man''s arm in on the left instead of being cut off, I would have scored this higher.', '2008-01-13 14:20:34.000000', NULL, 1),
(4389151, 630733, 41675, '<td valign="top">I think I get what you saw - using the brush as bushy eyes? If not, I''m missing what you were trying to get across and it simply looks like graffiti on a rock.</td>', 'I think I get what you saw - using the brush as bushy eyes? If not, I''m missing what you were trying to get across and it simply looks like graffiti on a rock.', '2008-01-13 14:21:52.000000', NULL, 1),
(4389153, 628532, 41675, '<td valign="top">I like the make up and the colors. For me, the background is distracting. Also, if it were a bit sharper, I would have scored it higher.</td>', 'I like the make up and the colors. For me, the background is distracting. Also, if it were a bit sharper, I would have scored it higher.', '2008-01-13 14:22:45.000000', NULL, 1),
(4389154, 628984, 41675, '<td valign="top">Your image seems a bit of a stretch for clowns - to me. I like the eyes themselves, but the lighting seems a bit too much.</td>', 'Your image seems a bit of a stretch for clowns - to me. I like the eyes themselves, but the lighting seems a bit too much.', '2008-01-13 14:23:33.000000', NULL, 1),
(4389158, 629236, 41675, '<td valign="top">It''s not a bad photo. It makes me think of a quick snapshot. Perhaps if it were taken from a lower angle looking up or zooming in on the clown and leaving out the name of the hotel, I would have scored it higher.</td>', 'It''s not a bad photo. It makes me think of a quick snapshot. Perhaps if it were taken from a lower angle looking up or zooming in on the clown and leaving out the name of the hotel, I would have scored it higher.', '2008-01-13 14:24:39.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4389163, 630786, 41675, '<td valign="top">The lack of focus and the...dullness of the colors (perhaps because of low lighting) keep this from really standing out for me.</td>', 'The lack of focus and the...dullness of the colors (perhaps because of low lighting) keep this from really standing out for me.', '2008-01-13 14:27:04.000000', NULL, 1),
(4389167, 630275, 41675, '<td valign="top">I like your gumball background and how it compliments the circles on the clown figurine. For me, it''s the lighting and lack of focus that keeps this from getting a higher score.</td>', 'I like your gumball background and how it compliments the circles on the clown figurine. For me, it''s the lighting and lack of focus that keeps this from getting a higher score.', '2008-01-13 14:28:37.000000', NULL, 1),
(4389356, 629861, 72070, '<td valign="top">really nice concept! the position of the kid, the use of light an the reflection really make it a good picture</td>', 'really nice concept! the position of the kid, the use of light an the reflection really make it a good picture', '2008-01-13 16:15:35.000000', NULL, 1),
(4389440, 630725, 58452, '<td valign="top">I see what you did here.  LOL  I wish you''d straightened out the ground and cropped the distant shore altogether. I like the play of the gull against the ranger with the pedometer.  Very nice.</td>', 'I see what you did here.  LOL  I wish you''d straightened out the ground and cropped the distant shore altogether. I like the play of the gull against the ranger with the pedometer.  Very nice.', '2008-01-13 17:11:43.000000', NULL, 1),
(4389518, 629695, 44754, '<td valign="top">really like the overall feel. would be nice even without that trashy clown.</td>', 'really like the overall feel. would be nice even without that trashy clown.', '2008-01-13 18:05:11.000000', NULL, 1),
(4389523, 630495, 44754, '<td valign="top">very cute. maybe would have gotten some of the "hair" away from the eye''s. Speaking of the eye''s, they seem a bit out of focus. Maybe locked on the nose?</td>', 'very cute. maybe would have gotten some of the "hair" away from the eye''s. Speaking of the eye''s, they seem a bit out of focus. Maybe locked on the nose?', '2008-01-13 18:07:48.000000', NULL, 1),
(4389525, 630786, 44754, '<td valign="top">Could maybe use a little brightening up.</td>', 'Could maybe use a little brightening up.', '2008-01-13 18:09:11.000000', NULL, 1),
(4389530, 630290, 44754, '<td valign="top">just a touch fill light and highlight boost. seems a bit too dark.</td>', 'just a touch fill light and highlight boost. seems a bit too dark.', '2008-01-13 18:13:05.000000', NULL, 1),
(4389610, 630300, 85679, '<td valign="top">It has red eye, the flash is a little bit harsh .</td>', 'It has red eye, the flash is a little bit harsh .', '2008-01-13 18:50:28.000000', NULL, 1),
(4389614, 629402, 85679, '<td valign="top">The flash is too harsh , there is no backround lighting and the detail in the first clown is blown out. i like the subject though.</td>', 'The flash is too harsh , there is no backround lighting and the detail in the first clown is blown out. i like the subject though.', '2008-01-13 18:55:04.000000', NULL, 1),
(4389617, 630733, 85679, '<td valign="top">I didd´t get the concept in it...sorry</td>', 'I didd´t get the concept in it...sorry', '2008-01-13 18:58:13.000000', NULL, 1),
(4390495, 630719, 88938, '<td valign="top">very intriguing photo!</td>', 'very intriguing photo!', '2008-01-14 01:24:16.000000', NULL, 1),
(4390499, 629286, 88938, '<td valign="top">very mood photograph!<br/>thumbs up!</td>', 'very mood photograph!thumbs up!', '2008-01-14 01:26:20.000000', NULL, 1),
(4390629, 630725, 74371, '<td valign="top">I have my doubts that this one will ribbon...but I totally love the idea behind the photo! Wonderful sense of humor!(7)</td>', 'I have my doubts that this one will ribbon...but I totally love the idea behind the photo! Wonderful sense of humor!(7)', '2008-01-14 03:18:38.000000', NULL, 1),
(4390630, 630276, 74371, '<td valign="top">I Love this photo. The feeling exhibited by the child (whether implied by the caption or for real) is outstanding! (9)</td>', 'I Love this photo. The feeling exhibited by the child (whether implied by the caption or for real) is outstanding! (9)', '2008-01-14 03:21:17.000000', NULL, 1),
(4390632, 630256, 74371, '<td valign="top">Colors are wonderful, the subject is grnd! Great photo! (9)</td>', 'Colors are wonderful, the subject is grnd! Great photo! (9)', '2008-01-14 03:26:43.000000', NULL, 1),
(4390859, 629402, 81382, '<td valign="top">Good documentary style shot, but with the flash lighting and distracting background I can''t see it scoring very highly here</td>', 'Good documentary style shot, but with the flash lighting and distracting background I can''t see it scoring very highly here', '2008-01-14 08:44:02.000000', NULL, 1),
(4390863, 630331, 81382, '<td valign="top">Got the eye in focus as it should be for a portrait style image, not a great fan of the lighting though I have to say, you have ended up with burnout highlights. A more diffused light source would have given a softer image. Painting with lighting might have also been worth considering - would have eliminated the colourful background too</td>', 'Got the eye in focus as it should be for a portrait style image, not a great fan of the lighting though I have to say, you have ended up with burnout highlights. A more diffused light source would have given a softer image. Painting with lighting might have also been worth considering - would have eliminated the colourful background too', '2008-01-14 08:46:17.000000', NULL, 1),
(4390866, 629274, 81382, '<td valign="top">Colours are not particularly vibrant and either the original was slightly soft or its not resized particularly well. I often add a final USM of 100, 0.5, 0 after resizing before I submit to a challenge</td>', 'Colours are not particularly vibrant and either the original was slightly soft or its not resized particularly well. I often add a final USM of 100, 0.5, 0 after resizing before I submit to a challenge', '2008-01-14 08:47:50.000000', NULL, 1),
(4390869, 629259, 81382, '<td valign="top">Nice dynamic angle and tight crop. Could be a little sharper on the eyes though to really make the image sing.</td>', 'Nice dynamic angle and tight crop. Could be a little sharper on the eyes though to really make the image sing.', '2008-01-14 08:48:54.000000', NULL, 1),
(4390872, 629951, 81382, '<td valign="top">Almost a too perfect background, would love to know how you did it within the rules. Not overly keen on the border although its good you''ve sampled average colours from the actual subject (a lot of entries don''t bother and it leads to inconsistent colour themes)</td>', 'Almost a too perfect background, would love to know how you did it within the rules. Not overly keen on the border although its good you''ve sampled average colours from the actual subject (a lot of entries don''t bother and it leads to inconsistent colour themes)', '2008-01-14 08:50:51.000000', NULL, 1),
(4390879, 630290, 81382, '<td valign="top">Lovely B&amp;W conversion, very different to the others which are all very vibrant as you would expect for clowns and so this makes for a welcome change. The B&amp;W really adds to the title and "retired clown" theme with the fork etc.. Nice not to see the face as well actually, just the trousers and shoes are enough and is quite subtle. My only problem is the border, why so wide</td>', 'Lovely B&W conversion, very different to the others which are all very vibrant as you would expect for clowns and so this makes for a welcome change. The B&W really adds to the title and "retired clown" theme with the fork etc.. Nice not to see the face as well actually, just the trousers and shoes are enough and is quite subtle. My only problem is the border, why so wide', '2008-01-14 08:53:30.000000', NULL, 1),
(4390884, 629286, 81382, '<td valign="top">Nice expression and title. Well composed, good focus on the eyes. Quite a dreary colour scheme and not vibrant at all like you might expect for a clown entry and it really reinforces your concept here. Well done.</td>', 'Nice expression and title. Well composed, good focus on the eyes. Quite a dreary colour scheme and not vibrant at all like you might expect for a clown entry and it really reinforces your concept here. Well done.', '2008-01-14 08:54:57.000000', NULL, 1),
(4390901, 630786, 81382, '<td valign="top">Whites of the eyes are quite dull, but under basic editing theres not a lot that can be done there. Not totally convinced the focus is fully on the eyes. The brightness of the bowtie is not matched but the colouring of the makeup and hair and so takes the focus away from the face</td>', 'Whites of the eyes are quite dull, but under basic editing theres not a lot that can be done there. Not totally convinced the focus is fully on the eyes. The brightness of the bowtie is not matched but the colouring of the makeup and hair and so takes the focus away from the face', '2008-01-14 09:02:46.000000', NULL, 1),
(4390906, 630275, 88254, '<td valign="top">Blurry.</td>', 'Blurry.', '2008-01-14 09:03:56.000000', NULL, 1),
(4390912, 630682, 88254, '<td valign="top">Blurry, shadows.</td>', 'Blurry, shadows.', '2008-01-14 09:07:18.000000', NULL, 1),
(4391282, 629236, 23098, '<td valign="top">Very nice.</td>', 'Very nice.', '2008-01-14 12:53:28.000000', NULL, 1),
