(4391303, 630276, 23098, '<td valign="top">Aww ...sweet shot, nice comp.</td>', 'Aww ...sweet shot, nice comp.', '2008-01-14 13:00:26.000000', NULL, 1),
(4391307, 630300, 23098, '<td valign="top">Sweet shot of a cute little clown.</td>', 'Sweet shot of a cute little clown.', '2008-01-14 13:01:51.000000', NULL, 1),
(4391310, 630307, 23098, '<td valign="top">Nice one.</td>', 'Nice one.', '2008-01-14 13:02:49.000000', NULL, 1),
(4391317, 630678, 23098, '<td valign="top">Good colors and detail.</td>', 'Good colors and detail.', '2008-01-14 13:05:37.000000', NULL, 1),
(4391341, 630719, 88825, '<td valign="top">Black and White makes this shot very effective.</td>', 'Black and White makes this shot very effective.', '2008-01-14 13:23:05.000000', NULL, 1),
