(4391346, 630782, 88825, '<td valign="top">You did a great job at getting the dog to stay put! The hat to the side is great.</td>', 'You did a great job at getting the dog to stay put! The hat to the side is great.', '2008-01-14 13:25:39.000000', NULL, 1),
