(4391351, 630478, 88825, '<td valign="top">I like how candid this shot feels.</td>', 'I like how candid this shot feels.', '2008-01-14 13:27:24.000000', NULL, 1),
(4391356, 629286, 88825, '<td valign="top">Nice timing... you can almost feel what he is thinking.</td>', 'Nice timing... you can almost feel what he is thinking.', '2008-01-14 13:29:03.000000', NULL, 1),
(4391358, 630776, 88825, '<td valign="top">I like how you reflected the images.</td>', 'I like how you reflected the images.', '2008-01-14 13:29:48.000000', NULL, 1),
