(4938292, 628579, 98210, '<td valign="top">I see you touched it up to make this clown look evil.<br/> <br/>The clown''s name is Veekay. Besides being an actor and a member of the "Wolf People" family, Veekay spends a lot of time visiting hospitals, convalescent homes, homes for the disabled, and support the Ronald McDonald House Charities, and The Make-A-Wish Foundation.<br/> <br/>You may learn more about Veekay at: <a href="//www.zootsuitclown.com" rel="nofollow" target="_blank">ZootSuitClown.com</a> <br/> <br/>and <br/><a href="//www.freaksarebeautifulpeople.com" rel="nofollow" target="_blank">freaksarebeautifulpeople.com</a><br/><br/><i>Message edited by author 2008-09-06 11:49:53.</i></td>', 'I see you touched it up to make this clown look evil. The clown''s name is Veekay. Besides being an actor and a member of the "Wolf People" family, Veekay spends a lot of time visiting hospitals, convalescent homes, homes for the disabled, and support the Ronald McDonald House Charities, and The Make-A-Wish Foundation. You may learn more about Veekay at: ZootSuitClown.com  and freaksarebeautifulpeople.com', '2008-09-06 12:47:45.000000', '2008-09-06 12:49:53.000000', 0),
(4938295, 628579, 98210, '<td valign="top">P.S. Veekay is a member of the Juaneno Band of Mission Indians, Acjachemen Nation.</td>', 'P.S. Veekay is a member of the Juaneno Band of Mission Indians, Acjachemen Nation.', '2008-09-06 12:49:01.000000', NULL, 0);
